//
// The deleted_at filter prevents stomping on a tombstoned row (revive
// runs its own UPDATE path that also clears deleted_at).
func (q *Queries) UpdateMeetingNoteOnResync(ctx context.Context, arg UpdateMeetingNoteOnResyncParams) (*MeetingNote, error) {
	row := q.db.QueryRow(ctx, UpdateMeetingNoteOnResync,
		arg.Title,
		arg.Summary,
		arg.Memo,
		arg.Participants,
		arg.LinkedKind,
		arg.LinkedID,
		arg.LinkageState,
		arg.InputHash,
		arg.ResolvedSetHash,
		arg.LastContentHash,
		arg.MeetingAt,
		arg.ConflictCandidates,
		arg.ID,
	)
	var i MeetingNote
	err := row.Scan(
		&i.ID,
		&i.AnarlogSessionID,
		&i.Title,
		&i.Summary,
		&i.Memo,
		&i.Participants,
		&i.MacHostID,
		&i.LinkedKind,
		&i.LinkedID,
		&i.LinkageState,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.InputHash,
		&i.ResolvedSetHash,
		&i.LastContentHash,
		&i.MeetingAt,
		&i.ConflictCandidates,
	)
	return &i, err
}
